mapper.delete:
DELETE FROM fgc.cap_check_detail
 WHERE cap_check_id = #{capCheckId}
   AND detail_seq > #{maxDetailSeq}

mapper.select:
SELECT cc.result_status AS resultStatus, COUNT(*) AS count
  FROM fgc.cap_check cc
  JOIN fgc.insurance_contract ic ON ic.contract_id = cc.contract_id


        AND date_trunc('month', cc.as_of_date) = date_trunc('month', #{month}::date)


        AND cc.payment_stage = #{paymentStage}


        AND ic.insurer_id = #{insurerId}


        AND ic.contract_no = #{contractNo}


 GROUP BY cc.result_status
